//lxrtxdy!
#include <bits/stdc++.h>
using namespace std;

using lint = long long;
constexpr lint INF = 1000000000;
constexpr int MAX_VER = 7100;

struct FlowNetwork {
    struct Edge {
        int u, v;
        lint f, c;
    };

    int source, sink;
    vector<Edge> E;
    vector<int> G[MAX_VER];
    int lvl[MAX_VER], ptr[MAX_VER];

    void reset() {
        E.clear();
        for (int i = 0; i < MAX_VER; ++i) G[i].clear();
    }

    void link(int u, int v, lint cap) {
        E.push_back({u, v, 0, cap});
        E.push_back({v, u, 0, 0});
        G[u].push_back((int)E.size() - 2);
        G[v].push_back((int)E.size() - 1);
    }

    bool level_graph() {
        memset(lvl, -1, sizeof(lvl));
        queue<int> Q;
        Q.push(source);
        lvl[source] = 0;

        while (!Q.empty()) {
            int u = Q.front(); Q.pop();
            for (int idx : G[u]) {
                auto &e = E[idx];
                if (e.c > e.f && lvl[e.v] == -1) {
                    lvl[e.v] = lvl[u] + 1;
                    Q.push(e.v);
                }
            }
        }
        return lvl[sink] != -1;
    }

    lint augment(int u, lint bottleneck) {
        if (u == sink || !bottleneck) return bottleneck;
        lint pushed = 0;
        for (int &i = ptr[u]; i < (int)G[u].size(); ++i) {
            int idx = G[u][i];
            auto &e = E[idx];
            if (lvl[e.v] == lvl[u] + 1 && e.c > e.f) {
                lint flow = augment(e.v, min(bottleneck, e.c - e.f));
                if (flow) {
                    e.f += flow;
                    E[idx ^ 1].f -= flow;
                    pushed += flow;
                    bottleneck -= flow;
                    if (!bottleneck) break;
                }
            }
        }
        return pushed;
    }

    lint max_flow() {
        lint total = 0;
        while (level_graph()) {
            memset(ptr, 0, sizeof(ptr));
            lint flow;
            while ((flow = augment(source, INF)) > 0)
                total += flow;
        }
        return total;
    }
};

FlowNetwork net;
char board1[14][14], board2[14][14];
bool vis_grid[14][14];
int time_grid[14][14];
int size_n, steps;
int final_node[103];

void propagate(int x, int y) {
    for (int i = 0; i < 14; ++i)
        fill(time_grid[i], time_grid[i] + 14, 111);
    queue<tuple<int, int, int>> q;
    time_grid[x][y] = 0;
    q.emplace(x, y, 0);

    const int dx[4] = {1, 0, 0, -1};
    const int dy[4] = {0, 1, -1, 0};

    while (!q.empty()) {
        auto [r, c, d] = q.front(); q.pop();
        if (vis_grid[r][c]) continue;
        vis_grid[r][c] = true;
        time_grid[r][c] = d;

        for (int i = 0; i < 4; ++i) {
            int nr = r + dx[i], nc = c + dy[i];
            if (nr >= 1 && nr <= size_n && nc >= 1 && nc <= size_n &&
                !vis_grid[nr][nc] && board1[nr][nc] != 'Y') {
                q.emplace(nr, nc, d + 1);
            }
        }
    }
}

int encode(int t, int r, int c) {
    return t * size_n * size_n + (r - 1) * size_n + c;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> size_n >> steps;
    for (int i = 1; i <= size_n; ++i) cin >> (board1[i] + 1);
    for (int i = 1; i <= size_n; ++i) cin >> (board2[i] + 1);

    net.reset();
    net.source = 0;
    net.sink = MAX_VER - 2;

    int start_r = 0, start_c = 0;
    for (int i = 1; i <= size_n; ++i) {
        for (int j = 1; j <= size_n; ++j) {
            if (board1[i][j] == 'Z') {
                start_r = i; start_c = j;
                break;
            }
        }
    }

    for (int i = 1; i <= size_n * size_n; ++i)
        final_node[i] = MAX_VER - 3 - (size_n * size_n - i);

    propagate(start_r, start_c);

    for (int i = 1; i <= size_n; ++i) {
        for (int j = 1; j <= size_n; ++j) {
            if (isdigit(board1[i][j]))
                net.link(net.source, encode(0, i, j), board1[i][j] - '0');
            if (isdigit(board2[i][j]))
                net.link(final_node[encode(0, i, j)], net.sink, board2[i][j] - '0');
            net.link(encode(0, i, j), final_node[encode(0, i, j)], INF);
        }
    }

    const int dx[4] = {1, 0, 0, -1};
    const int dy[4] = {0, 1, -1, 0};

    for (int t = 1; t <= steps; ++t) {
        for (int r = 1; r <= size_n; ++r) {
            for (int c = 1; c <= size_n; ++c) {
                if (board1[r][c] == 'Y' || board1[r][c] == 'Z') continue;
                for (int k = 0; k < 4; ++k) {
                    int nr = r + dx[k], nc = c + dy[k];
                    if (nr >= 1 && nr <= size_n && nc >= 1 && nc <= size_n &&
                        board1[nr][nc] != 'Y' && board1[nr][nc] != 'Z' &&
                        time_grid[r][c] >= t && time_grid[nr][nc] >= t) {
                        net.link(encode(t - 1, nr, nc), encode(t, r, c), INF);
                    }
                }
                net.link(encode(t, r, c), final_node[encode(0, r, c)], INF);
            }
        }
    }

    cout << net.max_flow() << '\n';
    return 0;
}
